import { attachControl, setCameraLimits, type ArcRotateCamera, type SceneContext } from "@babylonjs/lite";

function normalizeLimits(...) { ... }

export function attachLimitedOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  minDistance: number,
  maxDistance: number
): () => void {
  const [lower, upper] = normalizeLimits(minDistance, maxDistance);

  const clampRadius = (value: number): number => { ... };

  const previousLowerRadiusLimit = camera.lowerRadiusLimit;
  const previousUpperRadiusLimit = camera.upperRadiusLimit;

  let disposed = false;

  const enforce = (): void => {
    if (disposed) return;
    const current = camera.radius;
    const next = clampRadius(current);
    if (next !== current) camera.radius = next;
    if (!Number.isFinite(camera.inertialRadiusOffset)) camera.inertialRadiusOffset = 0;
    if (camera.radius === upper && camera.inertialRadiusOffset > 0) camera.inertialRadiusOffset = 0;
    if (camera.radius === lower && camera.inertialRadiusOffset < 0) camera.inertialRadiusOffset = 0;
    camera._clampToLimits?.();
  };

  const restoreLimits = (): void => {
    if (camera.lowerRadiusLimit === lower) camera.lowerRadiusLimit = previousLowerRadiusLimit;
    if (camera.upperRadiusLimit === upper) camera.upperRadiusLimit = previousUpperRadiusLimit;
  };

  camera.lowerRadiusLimit = lower;
  camera.upperRadiusLimit = upper;
  enforce();

  let disposeLimits = (): void => {};
  try {
    if (typeof setCameraLimits === "function") {
      const raw = setCameraLimits(camera, { lowerRadiusLimit: lower, upperRadiusLimit: upper }, scene);
      if (typeof raw === "function") disposeLimits = raw;
    }
  } catch (error) {
    restoreLimits();
    throw error;
  }

  let disposeControls = (): void => {};
  try {
    if (typeof attachControl === "function") {
      const raw = attachControl(camera, canvas, scene);
      if (typeof raw === "function") disposeControls = raw;
    }
  } catch (error) {
    disposeLimits();
    restoreLimits();
    throw error;
  }

  enforce();

  let frameId = 0;
  const raf = typeof globalThis.requestAnimationFrame === "function" ? globalThis.requestAnimationFrame : null;
  const cancelRaf = typeof globalThis.cancelAnimationFrame === "function" ? globalThis.cancelAnimationFrame : null;

  if (raf) {
    const loop = (): void => {
      if (disposed) return;
      enforce();
      frameId = raf(loop);
    };
    frameId = raf(loop);
  }

  return (): void => {
    if (disposed) return;
    disposed = true;
    if (frameId && cancelRaf) cancelRaf(frameId);
    disposeControls();
    disposeLimits();
    restoreLimits();
  };
}
```

