function registerRenderObserver(scene: SceneContext | null | undefined, callback: () => void): Disposer | null {
  if (!scene) return null;
  const s = scene as unknown as SceneWithRenderObservers;
  const candidates = [
    s.onBeforeRenderObservable,
    s.beforeRenderObservable,
    s.onRenderObservable,
    s.renderObservable,
    s.onAfterRenderObservable,
    s.afterRenderObservable,
  ];
  for (const obs of candidates) {
    if (!obs || typeof obs !== "object") continue;
    if (typeof obs.add !== "function") continue;
    const canRemoveDirectly = typeof obs.remove === "function" || typeof obs.removeObserver === "function";
    if (!canRemoveDirectly) continue;
    let result: unknown;
    try {
      result = obs.add(callback);
    } catch {
      if (typeof obs.remove === "function") { try { obs.remove(callback); } catch {} }
      if (typeof obs.removeObserver === "function") { try { obs.removeObserver(callback); } catch {} }
      continue;
    }
    if (typeof result === "function") return result as Disposer;
    if (result && typeof (result as { remove?: RemoveFunction }).remove === "function") {
      const remove = (result as { remove?: RemoveFunction }).remove;
      return () => { remove?.(callback); };
    }
    if (typeof obs.remove === "function") return () => obs.remove?.(callback);
    if (typeof obs.removeObserver === "function") return () => obs.removeObserver?.(callback);
